INSERT INTO internship_weekly_report (task_id, student_id, teacher_id, dept_id, week_number, start_date, end_date, deadline_time, work_content, work_summary, problem_encountered, next_week_plan, attachment_url, version, status, is_overdue, overdue_days, is_deleted, create_time, update_time) VALUES (2026, 1006, 1102, 1, 1, '2026-03-02', '2026-03-08', '2026-03-08 23:59:59', '本周参与了企业电商高并发中台的架构改造工作，深入理解了分布式锁与Redis多级缓存的设计机制，完成微服务骨干代码编写。', '本周整体开发进度符合项目预期规划，通过单元测试与压力测试排查出两个并发死锁隐患并完成修复，工作成效明显。', '在处理跨服务分布式事务一致性问题时遇到了TCC两阶段悬挂异常，经过与企业导师探讨后引入Seata解决。', '下周将重点接入消息队列削峰填谷模块，并开展灰度发布前的压测与容灾演练，保证业务稳定上线。', NULL, 1, 'DRAFT', 0, 0, 0, '2026-07-24 18:00:00', '2026-09-22 18:00:00');
